// Preset: a 128-bar FFT visualizer driven by the chip synth.
// The host wraps this body with the GLSL ES 1.0 Shadertoy template from
// programs/sdl2/renderer.c, which declares the uniforms used below
// (iResolution, iTime, iAudio). iAudio is a 128x1 GL_LUMINANCE texture
// holding the live magnitude spectrum (see programs/sdl2/audio.c):
// texture2D(iAudio, vec2(x, 0.0)).r is the level at normalized
// frequency x in [0, 1].
//
// Load this in the playground (or let it boot as the right-pane preset)
// and the bars must visibly react to the synth — bass on the left,
// highs on the right. A flat bar row means the audio ring is silent
// (e.g. muted via Ctrl+M, or a headless GL context with no audio pull).

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;

  // Sample the spectrum at this column. A small smoothing offset reads
  // two neighboring frequencies so the LINEAR-filtered texture gives
  // continuous bar heights rather than 128 hard steps.
  float level = texture2D(iAudio, vec2(uv.x, 0.0)).r;

  // Bar: lit below the level line, dark above. A bright cap near the
  // top of each bar reads as a peak meter.
  float bar = step(uv.y, level);
  float cap = smoothstep(level - 0.02, level, uv.y)
            * step(uv.y, level + 0.02);

  // Hue sweeps blue->magenta across the spectrum; brightness rises with
  // the bar level so loud bands glow.
  vec3 lowCol  = vec3(0.10, 0.45, 1.00);
  vec3 highCol = vec3(1.00, 0.25, 0.65);
  vec3 barCol  = mix(lowCol, highCol, uv.x) * (0.35 + 0.65 * level);

  vec3 bg = vec3(0.03, 0.03, 0.06);
  vec3 col = mix(bg, barCol, bar);
  col += cap * vec3(1.0);  // white peak cap

  fragColor = vec4(col, 1.0);
}

// Default Shadertoy-style image shader: a plasma over the right pane.
// The host wraps this body with the GLSL ES 1.0 Shadertoy template
// from programs/sdl2/main.c (FRAG_PREFIX / FRAG_SUFFIX), so this file
// only contains the `mainImage(out vec4 fragColor, in vec2 fragCoord)`
// entry point that the wrapper calls.
//
// Kept in sync with the built-in PLASMA_SRC fallback in
// programs/sdl2/main.c — if you edit one, edit both. The duplication
// is so the binary still renders when no VFS shader is staged (e.g.
// host/test/sdl2.test.ts under NodeKernelHost).

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  float r = 0.5 + 0.5 * sin(iTime + uv.x * 6.2831);
  float g = 0.5 + 0.5 * sin(iTime * 1.3 + uv.y * 6.2831);
  float b = 0.5 + 0.5 * sin(iTime * 0.7 + (uv.x + uv.y) * 6.2831);
  fragColor = vec4(r, g, b, 1.0);
}

// CC0: Trailing the Twinkling Tunnelwisp
//  A bit of Saturday coding (also Norway's Constitution Day).
//  Some artifacts remain, but it's good enough for my standards.
//
//  Music by Pestis created for Cassini's Cosmic Conclusion
//   https://demozoo.org/productions/367582/
//
//  Original (CC0) Shadertoy: https://www.shadertoy.com/view/WfcGWj
//
// Ported verbatim to GLSL ES 1.00 (our playground is WebGL1, the original
// is WebGL2/ES 3.00). The ONLY changes are dialect-level and do not alter
// the image: locals are zero-initialized, the golfed comma-operator
// for-loop is expanded into an equivalent explicit loop (identical math,
// identical order), and tanh() — absent in ES 1.00 — is provided by the
// tanh4() helper below. Everything else is the original code.

// Distance field for gyroid, adapted from Paul Karlik's "Gyroid Travel"
// in KodeLife. Tweaked slightly for this effect.
float g(vec4 p, float s) {
  // p.x=-abs(p.x);  // Makes it nicer (IMO) but costs bytes!
  return abs(dot(sin(p *= s), cos(p.zxwy)) - 1.) / s;
}

// tanh is a GLSL ES 3.00 builtin; emulate it for ES 1.00. Input is clamped
// so exp() can't overflow to Inf (which would yield NaN); tanh saturates
// well before |x|=15 so the clamp is invisible in the output.
vec4 tanh4(vec4 x) {
  x = clamp(x, -15., 15.);
  vec4 e = exp(2. * x);
  return (e - 1.) / (e + 1.);
}

void mainImage(out vec4 O, vec2 C) {
  float i = 0., d = 0., z = 0., s = 0., T = iTime;
  vec4 o = vec4(0.), q = vec4(0.), p = vec4(0.), U = vec4(2, 1, 0, 3);
  vec2 r = iResolution.xy;

  // Step through the scene, up to 78 steps. (Original used a single golfed
  // for-loop with all of the following packed into its comma-separated
  // increment clause; expanded here for ES 1.00 — same computation.)
  for (int n = 0; n < 78; n++) {
    // Accumulate glow — brighter and sharper if not mirrored (above axis).
    o += (s > 0. ? 1. : .1) * p.w * p / max(s > 0. ? d : d * d * d, 5E-4);

    // Advance along the ray by current distance estimate (+ epsilon).
    // The epsilon makes the cave walls somewhat translucent.
    z += d + 5E-4;
    // Compute ray direction, scaled by distance.
    q = vec4(normalize(vec3(C - .5 * r, r.y)) * z, .2);
    // Traverse through the cave.
    q.z += T / 3E1;
    // Save sign before mirroring.
    s = q.y + .1;
    // Creates the water reflection effect.
    q.y = abs(s);
    p = q;
    p.y -= .11;
    // Twist cave walls based on depth — the rotation matrix
    //   mat2(cos(a), sin(a), -sin(a), cos(a)) is approximated with
    //   mat2(cos(a + vec4(0,11,33,0))).
    p.xy *= mat2(cos(11. * U.zywz - 2. * p.z));
    p.y -= .2;
    // Combine gyroid fields at two scales for more detail.
    d = abs(g(p, 8.) - g(p, 24.)) / 4.;
    // Base glow color varies with distance from center.
    p = 1. + cos(.7 * U + 5. * q.z);
  }

  // Add pulsing glow for the "tunnelwisp".
  o += (1.4 + sin(T) * sin(1.7 * T) * sin(2.3 * T))
       * 1E3 * U / length(q.xy);

  // Apply tanh for soft tone mapping.
  O = tanh4(o / 1E5);
}

// Sound preset: a major-triad arpeggio.
// Steps through the notes of a C-major chord (C–E–G–C) four times a
// second, each note a plucked sine with a short decay envelope. Shows
// distinct FFT peaks marching up the spectrum in the iAudio visualizer.
// See programs/sdl2/sound_shader.c for the mainSound contract.
//
// Note: GLSL ES 1.00 fragment shaders don't allow dynamically-indexed
// local arrays, so the ratio is picked with an if-chain rather than
// array lookup.

float ratio_for(float step) {
  // Equal-temperament ratios for C, E, G, and the octave C.
  if (step < 0.5) return 1.0;       // C
  if (step < 1.5) return 1.2599;    // major third (E)
  if (step < 2.5) return 1.4983;    // perfect fifth (G)
  return 2.0;                       // octave C
}

vec2 mainSound(in float time) {
  float base = 261.63;                            // C4
  float step = floor(fract(time * 0.25) * 4.0);   // 0..3 over 4 s
  float freq = base * ratio_for(step);

  float note = fract(time * 4.0);   // 0..1 within each 1/4 s step
  float env = exp(-5.0 * note);
  float v = 0.4 * env * sin(6.2831853 * freq * time);
  return vec2(v, v);
}

// Sound preset: an FM bell that retriggers once per second.
// Two-operator frequency modulation — a sine carrier whose phase is
// modulated by a higher-frequency sine. The modulation index and the
// amplitude both decay across each one-second note (via fract(time)),
// giving the bright-attack / mellow-tail timbre of a struck bell.
// See programs/sdl2/sound_shader.c for the mainSound contract.

vec2 mainSound(in float time) {
  float note = fract(time);                 // 0..1 within each second
  float carrier = 440.0;
  float modulator = 880.0;
  float index = 5.0 * exp(-3.0 * note);     // FM brightness decays
  float env   = exp(-3.5 * note);           // amplitude decays
  float phase = 6.2831853 * carrier * time
              + index * sin(6.2831853 * modulator * time);
  float v = 0.4 * env * sin(phase);
  return vec2(v, v);
}

// Sound preset: white noise under a slow amplitude sweep.
// A cheap hash turns the per-sample time index into pseudo-random noise;
// a slow LFO sweeps the level so the FFT visualizer shows a broadband
// wash rising and falling. Good for confirming iAudio reacts across the
// whole spectrum (vs the single bins a sine lights up).
// See programs/sdl2/sound_shader.c for the mainSound contract.

float hash(float n) { return fract(sin(n) * 43758.5453123); }

vec2 mainSound(in float time) {
  // ~quantize to a noise rate so adjacent samples decorrelate.
  float n = hash(floor(time * 12000.0)) * 2.0 - 1.0;
  float sweep = 0.5 + 0.5 * sin(6.2831853 * 0.2 * time);
  float v = 0.3 * n * sweep;
  return vec2(v, v);
}

// Sound preset: a pure 220 Hz sine tone.
// A "sound shader" supplies `vec2 mainSound(in float time)` returning the
// (left, right) amplitude in [-1, 1] at `time` seconds. The host wraps
// this body with the GLSL ES 1.0 sound template from
// programs/sdl2/sound_shader.c, renders it to an FBO, reads it back, and
// plays the decoded PCM through ALSA. The image shader's iAudio uniform
// then visualizes this output's FFT — edit the sound, watch the picture.
//
// Kept in sync with BUILTIN_SOUND_SRC in programs/sdl2/main.c.

vec2 mainSound(in float time) {
  float v = 0.3 * sin(6.2831853 * 220.0 * time);
  return vec2(v, v);
}

// CC0: Trailing the Twinkling Tunnelwisp
//  A bit of Saturday coding (also Norway's Constitution Day).
//  Some artifacts remain, but it's good enough for my standards.
//
//  Music by Pestis created for Cassini's Cosmic Conclusion
//   https://demozoo.org/productions/367582/
//
//  Original (CC0) Shadertoy: https://www.shadertoy.com/view/WfcGWj
//
// Ported verbatim to GLSL ES 1.00. Dialect-level changes only — the
// synthesis math is unchanged:
//   - Shadertoy's signature is mainSound(int samp, float time); the int
//     sample index is unused here, and our host template calls
//     mainSound(time), so the parameter is dropped.
//   - Locals are zero-initialized (ES 1.00 has no implicit zero-init).
//   - The golfed `for(c=3.;c<4.1;n+=c*=1.02)` inner loop is expanded into
//     an explicit constant-bound loop producing the identical sequence.
//
// NOTE: this composition evolves over minutes, but our sound-shader buffer
// is fixed (~2.73 s) and loops, so only the opening plays, repeating. The
// image is continuously iTime-animated and is unaffected.

vec2 mainSound(in float t) {
  // Accumulator for the final sound output.
  vec2 r = vec2(0.);

  // a controls the overall progression; b is its fractional part.
  for (float i = 1.; i < 4.; i++)
  for (float j = 1.; j < 5.; j++) {
    float a = t * j / 32. + i / 3., b = fract(a);

    // n is the base frequency vector (slight stereo offset); m accumulates
    // harmonics.
    vec2 m = vec2(0.), n = vec2(t, t + 3.) + t / j;

    // Sum sine harmonics with a gradually increasing frequency multiplier
    // and 1/c amplitude falloff. (Original: for(c=3.;c<4.1;n+=c*=1.02).)
    float c = 3.;
    for (int k = 0; k < 16; k++) {
      if (c >= 4.1) break;
      m += sin(n * c) / c;
      c *= 1.02;
      n += c;
    }

    // Only contribute sound during the first part of the composition.
    if (a < 9.)
      r += sin(
             m
             + 4. * sin(t / j / 47.)
               * sin(exp2(mod(a - b, 3.) / 6. + 8.5) * t * j * i + i + j)
           )
           * exp2(-b * 12. - 1. / b + 6. - (i + j) / 3.);
  }

  return r;
}

