user nobody;
daemon off;
master_process on;
worker_processes 2;
error_log stderr info;
pid /tmp/nginx.pid;

events {
    worker_connections 64;
    use poll;
}

http {
    access_log /dev/stderr;
    client_body_temp_path /tmp/nginx_client_temp;
    proxy_temp_path /tmp/nginx_proxy_temp;
    fastcgi_temp_path /tmp/nginx_fastcgi_temp;

    types {
        text/html                             html htm;
        text/css                              css;
        text/javascript                       js;
        application/json                      json;
        image/png                             png;
        image/jpeg                            jpg jpeg;
        image/gif                             gif;
        image/svg+xml                         svg;
        application/octet-stream              bin;
    }
    default_type application/octet-stream;

    server {
        listen 8080;
        server_name localhost;
        root /srv/www/html;
        include /etc/nginx/default.d/*.conf;
    }
}

#!/usr/local/bin/php -n
<?php
$action = $argv[1] ?? '';
$value = $argv[2] ?? '';
$body = match ($action) {
    'ideas' => null,
    'add' => ['action' => 'add', 'title' => $value],
    'vote' => ['action' => 'vote', 'id' => $value],
    default => false,
};
if ($body === false) {
    fwrite(STDERR, "usage: redis-board ideas | add <title> | vote <id>\n");
    exit(2);
}
$http = ['ignore_errors' => true];
if ($body !== null) $http += ['method' => 'POST', 'header' => "Content-Type: application/json\r\n", 'content' => json_encode($body)];
$response = @file_get_contents('http://127.0.0.1:8080/api', false, stream_context_create(['http' => $http]));
if ($response === false) {
    fwrite(STDERR, "redis-board: the board on port 8080 does not answer\n");
    exit(1);
}
echo $response, "\n";
exit(preg_match('~^HTTP/\S+ 200 ~', $http_response_header[0] ?? '') === 1 ? 0 : 1);

